class Solet < Formula
  include Language::Python::Virtualenv

  desc "Create and operate local Solet instances"
  homepage "https://solet.ai"
  url "https://github.com/solet-public/homebrew-tap/releases/download/manager-v0.1.0-r59/solet-0.1.0-r59.tar.gz"
  sha256 "85372b6d0ac23af543656fc6987d1c5303d1dc437196f8909b445885e2b8ace6"
  license "Apache-2.0"
  revision 34
  depends_on "git"
  depends_on "python@3.13"

  resource "setuptools" do
    url "https://files.pythonhosted.org/packages/95/9c/c510029fc6ef33a6275cd2c5d3cecd6613dfd6aa401d57c54f1c18852ccf/setuptools-84.0.0-py3-none-any.whl"
    sha256 "51a52592b3b99e102b609654876bd65f19f999935166d1352678931132b0c670"
  end

  resource "wheel" do
    url "https://files.pythonhosted.org/packages/2e/29/69cfbb602cd91690c55d38ba9fe53e6a7e76a6fa647bf38f19c138d25449/wheel-0.48.0-py3-none-any.whl"
    sha256 "3217dcc807155e45db462d7ef2431f5ddda0d7273b700d05a67b271ceb1287ab"
  end

  # solet_manager imports packaging.requirements at runtime (the manager's
  # own dependency, not a build-time one — no build backend needs it).
  # Declared in solet_cli/pyproject.toml's dependencies list AND vendored
  # here: this install is --no-deps/--no-index, so pip never consults that
  # declaration to decide what's importable — only what's actually staged
  # into the venv does, which is what this resource provides.
  resource "packaging" do
    url "https://files.pythonhosted.org/packages/df/b2/87e62e8c3e2f4b32e5fe99e0b86d576da1312593b39f47d8ceef365e95ed/packaging-26.2-py3-none-any.whl"
    sha256 "5fc45236b9446107ff2415ce77c807cee2862cb6fac22b8a73826d0693b0980e"
  end

  def install
    venv = virtualenv_create(libexec, "python3.13")
    # Homebrew's python@3.13 provisions pip and wheel via ensurepip but never
    # setuptools (measured: its post-install log installs only pip, wheel).
    # solet_cli's build backend is setuptools.build_meta, so build_isolation
    # below needs setuptools present without hitting the network — vendor it
    # as a pinned, checksummed resource instead of assuming the machine has
    # one lying around.
    venv.pip_install resources
    venv.pip_install buildpath/"solet_setup_contracts", build_isolation: false
    venv.pip_install buildpath/"solet_cli", build_isolation: false

    (libexec/"share"/"solet"/"contracts").install Dir[
      "plugins/github_midwife_plugin/knowledge_base/macos_setup_flow.json",
      "plugins/github_midwife_plugin/knowledge_base/setup_flow.schema.json",
      "plugins/github_midwife_plugin/knowledge_base/setup_answers.schema.json",
      "plugins/github_midwife_plugin/knowledge_base/setup_journal.schema.json",
      "plugins/github_midwife_plugin/knowledge_base/setup_adapter_envelope.schema.json",
      "plugins/github_midwife_plugin/knowledge_base/permissions_manifest.json",
      "plugins/github_midwife_plugin/knowledge_base/existing_install_flow.json",
      "plugins/github_midwife_plugin/knowledge_base/existing_install_flow.schema.json",
    ]
    # Homebrew's build sandbox forbids reading the tap checkout while a Formula
    # installs. Render the same reviewed lock bytes into the Formula so the
    # default lock remains non-circular without crossing that sandbox boundary.
    (libexec/"share"/"solet"/"seed.lock.json").write <<~'JSON'
      {
        "schema_version": 3,
        "channel_id": "stable",
        "repository": "https://github.com/solet-public/macos-bizops.git",
        "release_tag": "release-2026-09-29-6b292e918e83",
        "commit": "6b292e918e83520afbb4eecd79da67766a35d538",
        "tree_hash": "8b75d9eb6437a03708c5dd5925b6b5f22c328b1b",
        "archive_sha256": "85372b6d0ac23af543656fc6987d1c5303d1dc437196f8909b445885e2b8ace6",
        "profile": "macos-bizops",
        "provenance": {"bundle_name":"macos-bizops","manifest_sha256":"5aa96e091254b6dd58d2937350ce52bb2f06fb97d9967ad2e974ee0706246049","origin_id":"31bfa93c-fe20-4988-b019-f8186684e88e","platform":"local","provenance_sha256":"39ba71b59a03491f5f89c70ad8f8a3ab02d2828ba8c72fb59aa143be6d0733db","schema_version":1,"seed_id":"1281d2df-55e1-5ad4-95dc-0a2d7b45225a","source_commit":"ff0cdc8d01afb3e37cea4a4402b930ad05880ad8","source_date":"2026-09-29T06:30:22-07:00"},
        "existing_install_contract": {"bundle_digest":"sha256:e22f09f3de02b255d46bb9f3a6ce9e271fb57e06bb4b1e697799842a8a11c716","flow_id":"existing-install","flow_schema_version":1},
        "allowed_repository_migrations": []
      }
    JSON
    # The bundled catalog's anchor_table_sha256 is static wheel package data
    # (solet_cli/src/solet_manager/released_metadata/), but a channel's
    # seed_lock_sha256 must equal sha256 of the file above, which embeds this
    # release's own payload digest -- unknowable until the payload already
    # exists. Render it here, release-side, like the lock itself, instead of
    # baking an impossible self-reference into the wheel.
    (libexec/"share"/"solet"/"existing_install_inspection_seed_lock_catalog.v1.json").write <<~'JSON'
      {
        "schema_version": 1,
        "channels": [
          {
            "channel_id": "stable",
            "seed_lock_sha256": "5103b789abcdd16dfbdb67c379e85f73a8feae9b46022c81377a774208d93f0a"
          }
        ]
      }
    JSON
    # This installed receipt distinguishes a worktree-payload experiment from
    # a published manager/seed pair.  It is deliberately independent of the
    # seed lock: the latter authenticates the seed, while this records how the
    # manager archive itself reached this keg.
    (libexec/"share"/"solet"/"install-source.json").write <<~'JSON'
      {
        "schema_version": 1,
        "mode": "release",
        "source_commit": "ff0cdc8d01afb3e37cea4a4402b930ad05880ad8"
      }
    JSON
    # The stage-5 draft `release_manifest.json` (design §7.1) `stage_release.py`
    # writes beside this Formula, unchanged. `solet_manager.release_identity_gate`
    # reads its manifest from this exact keg path -- installing it is what lets
    # a manifest-recorded `allow_manager_seed_skew` reason reach the gate
    # (iss_18c47206). The `tap`/`surface_digests`/... sections a later
    # `publish_release` stage would own are already `null` in this draft.
    # QUOTED heredoc delimiter deliberately (`<<~'JSON'`, not `<<~JSON`): an
    # unquoted heredoc is double-quote semantics in Ruby, so `\`/`"`/newline
    # in a free-text `allow_manager_seed_skew` reason get re-escaped into an
    # unparseable keg manifest, and `#{...}` in that reason would execute as
    # Ruby when this Formula installs -- a code-injection sink in a shipped
    # Formula. Verified with Homebrew's own portable Ruby (review of this
    # unit, BLOCK, `reissue_manifest_in_keg_review.md`).
    (libexec/"share"/"solet"/"release_manifest.json").write <<~'JSON'
      {"bundle_verdict":null,"components":null,"factory_signature":null,"guest_validation":null,"manager":{"allow_manager_seed_skew":null,"contract_digest":"sha256:19350a8d3b0b29139afe25b6f11648c0f3f2e1fdb8ca91f81d5bfa1280fc7492","file_digests":{"LICENSE":"sha256:cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30","NOTICE":"sha256:ae7a7a5d43af10e205e32c7d401dad1794b585d65a1c436db352210975843a7e","plugins/github_midwife_plugin/knowledge_base/existing_install_flow.json":"sha256:456ce71c17d9a4a118c62dee2c3c30023c32ca10d1593cb66f288bb1c4c54404","plugins/github_midwife_plugin/knowledge_base/existing_install_flow.schema.json":"sha256:fa1a3ab7f8726b1db01b5361f91c8b25875055138d5d70ce6d516e79728847db","plugins/github_midwife_plugin/knowledge_base/macos_setup_flow.json":"sha256:ef9c5aa754b2d3e32a4161e05ffbc554c830615edd68749ae81a9ee52439820b","plugins/github_midwife_plugin/knowledge_base/permissions_manifest.json":"sha256:964c23d4b570fac1679c081e05521acb1377a5436f40c3a2589d7000532231bf","plugins/github_midwife_plugin/knowledge_base/setup_adapter_envelope.schema.json":"sha256:bde25563f85a1d7a8dce96fa165aa279844c11149856ce70dda5f4b3b3a2714f","plugins/github_midwife_plugin/knowledge_base/setup_answers.schema.json":"sha256:025c28c0780f9b521f7ae7ad0a3dbba3c45a8cd83d1b1cc8b0adcd5f696af8e1","plugins/github_midwife_plugin/knowledge_base/setup_flow.schema.json":"sha256:0714203b618cc32fa6b068cbb1d65fed5a97f4f91ec7868eae5a8698c9e44877","plugins/github_midwife_plugin/knowledge_base/setup_journal.schema.json":"sha256:0828b597e84fe77c0f2b3b6e352fafe88ac17352da99bf7a30d6a5e304327a1b","solet_cli/homebrew/Formula/solet.rb.template":"sha256:4dfb8ce11a018f3d97c5848dae27fd5bb0b7df2c4a0c2ea8ba99df3c9c2c6ef3","solet_cli/homebrew/README.md":"sha256:6b40a54d615caa8ece8a5b50c02be9be779e74a3de99b3c323037e2b63e8bd46","solet_cli/homebrew/ci/Brewfile.enterprise.example":"sha256:1afa7b8664120635eaadee90bda2f698c38b68e9c8cdc47f9934b2fbadd6209b","solet_cli/homebrew/ci/__init__.py":"sha256:976f